<?php require_role('admin');require_once 'app/helpers.php';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=[$_POST['audience'],trim($_POST['title_en']),trim($_POST['title_ta']),trim($_POST['description']), (int)$_POST['sort_order']];if($id){$s=db()->prepare('UPDATE topics SET audience=?,title_en=?,title_ta=?,description=?,sort_order=? WHERE id=?');$s->execute([...$d,$id]);}else{$s=db()->prepare('INSERT INTO topics(audience,title_en,title_ta,description,sort_order) VALUES(?,?,?,?,?)');$s->execute($d);}header('Location: admin.php');exit;} $t=$id?db()->query('SELECT * FROM topics WHERE id='.$id)->fetch():['audience'=>'public','title_en'=>'','title_ta'=>'','description'=>'','sort_order'=>1];$page_title='Topic Editor';include 'partials/header.php';?><div class="card"><h1><?=($id?'Edit':'Add')?> Topic</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-group"><label>Audience</label><select name="audience"><option value="public" <?=$t['audience']==='public'?'selected':''?>>Parent / General Public</option><option value="professional" <?=$t['audience']==='professional'?'selected':''?>>Professional</option></select></div><div class="form-group"><label>Title (English)</label><input name="title_en" value="<?=e($t['title_en'])?>" required></div><div class="form-group"><label>Title (Tamil)</label><input name="title_ta" value="<?=e($t['title_ta'])?>"></div><div class="form-group"><label>Description</label><textarea name="description"><?=e($t['description'])?></textarea></div><div class="form-group"><label>Sort order</label><input type="number" name="sort_order" value="<?=e($t['sort_order'])?>"></div><button class="btn">Save</button> <a class="btn secondary" href="admin.php">Cancel</a></form></div><?php include 'partials/footer.php';?>
